/* ============================================================
   INSCRIÇÃO
   ============================================================ */
function Inscricao({ settings, inscricoesEncerradas, vagasRestantes, onSubmit }) {
  const [form, setForm] = useState({
    name: "", email: "", whatsapp: "", institution: "", city: "",
  });
  const [agree, setAgree] = useState(false);
  const [error, setError] = useState("");
  const [submitting, setSubmitting] = useState(false);

  function update(field, value) {
    setForm((f) => ({ ...f, [field]: value }));
  }

  async function handleSubmit(e) {
    e.preventDefault();
    setSubmitting(true);
    setError("");

    if (!form.name || !form.email || !form.whatsapp || !form.institution || !form.city) {
      setError("Preencha todos os campos para continuar.");
      setSubmitting(false);
      return;
    }
    if (!agree) {
      setError("É necessário aceitar o uso dos dados para concluir a inscrição.");
      setSubmitting(false);
      return;
    }

    try {
      const { error: supabaseError } = await supabase.from("inscricoes").insert([
        {
          nome: form.name,
          email: form.email,
          whatsapp: form.whatsapp,
          instituicao: form.institution,
          cidade: form.city,
        },
      ]);

      if (supabaseError) {
        console.error("Supabase - falha ao gravar inscrição:", supabaseError);
        setError("Não foi possível concluir sua inscrição agora. Tente novamente em instantes.");
        setSubmitting(false);
        return;
      }

      await onSubmit(form);
    } catch (err) {
      console.error("Supabase - erro de conexão ao gravar inscrição:", err);
      setError("Não foi possível concluir sua inscrição agora. Verifique sua conexão e tente novamente.");
    }
    setSubmitting(false);
  }

  if (inscricoesEncerradas) {
    return (
      <section id="inscricao" className="px-5 py-16 md:py-20" style={{ background: NAVY }}>
        <div className="max-w-xl mx-auto text-center">
          <h2 className="font-serif-brand text-2xl md:text-3xl font-bold text-white">Inscrições encerradas</h2>
          <p className="text-white/70 mt-3 text-sm">Todas as vagas para esta oficina já foram preenchidas. Acompanhe nossos canais para futuras edições.</p>
        </div>
      </section>
    );
  }

  return (
    <section id="inscricao" className="px-5 py-16 md:py-20" style={{ background: NAVY }}>
      <div className="max-w-xl mx-auto">
        <div className="text-center mb-8">
          <p className="text-xs font-semibold uppercase tracking-widest" style={{ color: GOLD_LIGHT }}>Garanta sua vaga</p>
          <h2 className="font-serif-brand text-2xl md:text-3xl font-bold mt-2 text-white">Faça sua inscrição</h2>
          <p className="text-white/60 text-xs mt-2">{vagasRestantes} vaga{vagasRestantes === 1 ? "" : "s"} restante{vagasRestantes === 1 ? "" : "s"} de {settings.maxSlots}</p>
        </div>

        <form onSubmit={handleSubmit} className="bg-white rounded-2xl p-6 md:p-8 shadow-lg space-y-4">
          <Field label="Nome completo"><input className="input" value={form.name} onChange={(e) => update("name", e.target.value)} placeholder="Seu nome completo" /></Field>
          <Field label="WhatsApp"><input className="input" value={form.whatsapp} onChange={(e) => update("whatsapp", e.target.value)} placeholder="(99) 99999-9999" /></Field>
          <Field label="E-mail"><input type="email" className="input" value={form.email} onChange={(e) => update("email", e.target.value)} placeholder="voce@email.com" /></Field>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Instituição ou empresa"><input className="input" value={form.institution} onChange={(e) => update("institution", e.target.value)} placeholder="Ex.: IFMA" /></Field>
            <Field label="Cidade"><input className="input" value={form.city} onChange={(e) => update("city", e.target.value)} placeholder="Sua cidade" /></Field>
          </div>

          <label className="flex items-start gap-2.5 pt-2 cursor-pointer">
            <input type="checkbox" checked={agree} onChange={(e) => setAgree(e.target.checked)} className="mt-1 w-4 h-4 flex-shrink-0" />
            <span className="text-xs leading-relaxed" style={{ color: "#5A6B7D" }}>
              Declaro que as informações fornecidas são verdadeiras e autorizo a utilização desses dados exclusivamente para organização do evento e emissão do certificado.
            </span>
          </label>

          {error && <p className="text-xs font-medium" style={{ color: "#B3261E" }}>{error}</p>}

          <button
            type="submit"
            disabled={submitting}
            className="w-full py-3.5 rounded-full font-semibold text-sm transition hover:brightness-95 disabled:opacity-60"
            style={{ background: GOLD, color: NAVY }}
          >
            {submitting ? "Enviando…" : "Realizar inscrição"}
          </button>

          <style>{`.input{ width:100%; padding:.65rem .85rem; border-radius:.6rem; border:1px solid #D6DFE9; font-size:.875rem; outline:none; } .input:focus{ border-color:${BLUE}; box-shadow:0 0 0 3px ${BLUE}22; }`}</style>
        </form>
      </div>
    </section>
  );
}

function Field({ label, children }) {
  return (
    <label className="block">
      <span className="block text-xs font-medium mb-1.5" style={{ color: "#3B4E63" }}>{label}</span>
      {children}
    </label>
  );
}

