/* ============================================================
   CERTIFICADO — EMISSÃO
   ============================================================ */
function CertificadoView({ settings, participants, onBack, persist, data }) {
  const [query, setQuery] = useState("");
  const [result, setResult] = useState(null); // 'not_found' | 'no_presence' | participant object
  const printRef = useRef(null);

  async function handleSearch(e) {
    e.preventDefault();
    const q = query.trim().toLowerCase();
    const found = participants.find((p) => p.email.toLowerCase() === q);
    if (!found) {
      setResult("not_found");
      return;
    }
    if (found.status !== "presente") {
      setResult("no_presence");
      return;
    }
    let updated = found;
    if (!found.certCode) {
  const newCertCode = genCode();

  const { error } = await supabase
    .from("inscricoes")
    .update({
      certificado_emitido: true,
      codigo_certificado: newCertCode,
    })
    .eq("id", found.id);

  if (error) {
    console.error("Erro ao emitir certificado:", error);
    return;
  }

  updated = { ...found, certCode: newCertCode };

  const nextParticipants = participants.map((p) =>
    p.id === found.id ? updated : p
  );

  await persist({
    settings: data.settings,
    participants: nextParticipants,
  });
}
    setResult(updated);
    }

  return (
    <div className="min-h-screen px-5 py-14" style={{ background: LIGHT }}>
      <div className="max-w-md mx-auto">
        <button onClick={onBack} className="no-print flex items-center gap-1.5 text-sm mb-6" style={{ color: BLUE }}>
          <ArrowLeft size={16} /> Voltar ao início
        </button>

        <div className="text-center mb-6">
          <FileCheck2 size={28} color={NAVY} className="mx-auto" />
          <h1 className="font-serif-brand text-xl font-bold mt-3" style={{ color: NAVY }}>Emitir meu certificado</h1>
          <p className="text-sm mt-1" style={{ color: "#5A6B7D" }}>Informe o e-mail utilizado na inscrição.</p>
        </div>

        <form onSubmit={handleSearch} className="no-print bg-white rounded-2xl p-5 shadow-sm border flex gap-2" style={{ borderColor: "#E3E9F0" }}>
          <input type="email" className="flex-1 px-3 py-2.5 rounded-lg border text-sm outline-none" style={{ borderColor: "#D6DFE9" }} placeholder="voce@email.com" value={query} onChange={(e) => setQuery(e.target.value)} />
          <button className="px-4 rounded-lg" style={{ background: NAVY }}><Search size={18} color="white" /></button>
        </form>

        {result === "not_found" && (
          <p className="text-sm text-center mt-6" style={{ color: "#B3261E" }}>Não encontramos nenhuma inscrição com esse e-mail.</p>
        )}
        {result === "no_presence" && (
          <p className="text-sm text-center mt-6 leading-relaxed" style={{ color: "#B3261E" }}>
            Certificado ainda não disponível. Verifique se sua presença foi registrada durante o evento.
          </p>
        )}
        {result && typeof result === "object" && (
          <div className="mt-6">
            <div className="bg-white rounded-2xl p-5 shadow-sm border text-center mb-4" style={{ borderColor: "#E3E9F0" }}>
              <CheckCircle2 size={22} color="#1E8E3E" className="mx-auto" />
              <p className="text-sm font-semibold mt-2" style={{ color: NAVY }}>Certificado disponível</p>
            </div>
            <CertificateCard ref={printRef} settings={settings} participant={result} />
            <button onClick={() => window.print()} className="no-print w-full mt-4 py-3 rounded-full font-semibold text-sm flex items-center justify-center gap-2" style={{ background: GOLD, color: NAVY }}>
              <Download size={16} /> Baixar certificado
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
